svg.script:
const svg = document.getElementById('b');
const dragContainer = document.getElementById('drag-container');
let selectedElement = false;
let offset;

// Function to convert screen pixels to SVG coordinates
function getMousePosition(evt) {
    const CTM = svg.getScreenCTM();
    return {
        x: (evt.clientX - CTM.e) / CTM.a,
        y: (evt.clientY - CTM.f) / CTM.d
    };
}

svg.addEventListener('mousedown', (evt) => {
    if (evt.target.classList.contains('e')) {
        selectedElement = dragContainer;
        offset = getMousePosition(evt);

        // Calculate initial offset between mouse and element position
        const transforms = selectedElement.transform.baseVal;
        if (transforms.length === 0 || transforms.getItem(0).type !== SVGTransform.SVG_TRANSFORM_TRANSLATE) {
            const translate = svg.createSVGTransform();
            translate.setTranslate(0, 0);
            selectedElement.transform.baseVal.insertItemBefore(translate, 0);
        }

        const transform = transforms.getItem(0);
        offset.x -= transform.matrix.e;
        offset.y -= transform.matrix.f;
    }
});

svg.addEventListener('mousemove', (evt) => {
    if (selectedElement) {
        evt.preventDefault();
        const coord = getMousePosition(evt);
        const transform = selectedElement.transform.baseVal.getItem(0);
        transform.setTranslate(coord.x - offset.x, coord.y - offset.y);
    }
});

svg.addEventListener('mouseup', () => {
    selectedElement = null;
});

svg.addEventListener('mouseleave', () => {
    selectedElement = null;
});
